const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Tuz geometry (approximate center and buffer)
  const lakeTuz = ee.Geometry.Point([33.4, 38.5]).buffer(25000); // 25km radius

  // 2. Data acquisition for August 1988 (Landsat 5)
  let col1988 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(lakeTuz)
    .filter(ee.Filter.calendarRange(1988, 1988, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  const size1988 = col1988.size().getInfo();
  console.log(`1988 Images found: ${size1988}`);

  if (size1988 === 0) {
    console.log('No Landsat 5 data for August 1988');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Data acquisition for August 2016 (Landsat 8)
  let col2016 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(lakeTuz)
    .filter(ee.Filter.calendarRange(2016, 2016, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  const size2016 = col2016.size().getInfo();
  console.log(`2016 Images found: ${size2016}`);

  if (size2016 === 0) {
    console.log('No Landsat 8 data for August 2016');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Cloud masking function for Landsat
  function maskL8Clouds(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  function maskL5Clouds(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  // 5. Calculate MNDWI and water area for 1988
  const img1988 = col1988.map(maskL5Clouds).median();
  const mndwi1988 = img1988.normalizedDifference(['SR_B2', 'SR_B5']).rename('MNDWI');
  const water1988 = mndwi1988.gt(0);

  const stats1988 = water1988.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: lakeTuz,
    scale: 3000,
    maxPixels: 1e9
  });

  const waterPixels1988 = stats1988.get('MNDWI_sum').getInfo();
  const totalPixels1988 = stats1988.get('MNDWI_count').getInfo();

  console.log(`1988 - Water pixels: ${waterPixels1988}, Total pixels: ${totalPixels1988}`);

  if (totalPixels1988 === 0) {
    console.log('No valid pixels for 1988 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Calculate MNDWI and water area for 2016
  const img2016 = col2016.map(maskL8Clouds).median();
  const mndwi2016 = img2016.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
  const water2016 = mndwi2016.gt(0);

  const stats2016 = water2016.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: lakeTuz,
    scale: 3000,
    maxPixels: 1e9
  });

  const waterPixels2016 = stats2016.get('MNDWI_sum').getInfo();
  const totalPixels2016 = stats2016.get('MNDWI_count').getInfo();

  console.log(`2016 - Water pixels: ${waterPixels2016}, Total pixels: ${totalPixels2016}`);

  if (totalPixels2016 === 0) {
    console.log('No valid pixels for 2016 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Validation and comparison
  if (waterPixels1988 === null || waterPixels2016 === null || 
      waterPixels1988 === undefined || waterPixels2016 === undefined) {
    console.log('Calculation failed - invalid results');
    console.log('<answer>C3</answer>');
    return;
  }

  const area1988 = waterPixels1988 * 9; // 3000m scale = 9 km² per pixel
  const area2016 = waterPixels2016 * 9;

  console.log(`Lake Tuz water area - 1988: ${area1988.toFixed(2)} km²`);
  console.log(`Lake Tuz water area - 2016: ${area2016.toFixed(2)} km²`);
  console.log(`Change: ${(area2016 - area1988).toFixed(2)} km²`);

  if (area2016 < area1988) {
    console.log('Water surface area DECREASED in 2016');
    console.log('<answer>A</answer>');
  } else {
    console.log('Water surface area did NOT decrease in 2016');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
